PartProcessCharacteristic Resolve(ChemicalRow r,List<PartProcessCharacteristic> all){var matches=all.Where(x=>LineMatch(r.Line,r.Sheet,x.Machine!.MachineCode)&&Canon(x.Tank!.TankName)==Canon(r.Slot)&&CanonItem(x.Characteristic!.CharacteristicName)==CanonItem(r.Item)).ToList();if(matches.Count!=1)throw new Exception("Master mapping failed: "+r.Key);return matches[0];}
static bool LineMatch(string line,string sheet,string machine){var source=Canon(line);if(source is "PT" or "QE" or "ST" or "DV")source+=Canon(sheet)=="舊線"?"1":"2";return source==Canon(machine);}
static string Canon(string? value){var first=(value??"").Replace('\r','\n').Split('\n',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries).FirstOrDefault()??"";return new string(first.Normalize(NormalizationForm.FormKC).ToUpperInvariant().Where(char.IsLetterOrDigit).ToArray());}
static string CanonItem(string? value){var first=(value??"").Replace('\r','\n').Split('\n',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries).FirstOrDefault()??"";return Canon(System.Text.RegularExpressions.Regex.Replace(first,@"\([^)]*\)|（[^）]*）|\[[^]]*\]",""));}
static ChemicalPreviewInput Input(ChemicalPlan p)=>new(MeasuredAt(p.Row).ToString("o"),p.Row.Primary.ToString(CultureInfo.InvariantCulture),null,JsonSerializer.Serialize(new{kind="TransFilesChemical-v3",fileHash=p.Row.Hash,file=p.Row.File,sheet=p.Row.Sheet,row=p.Row.SourceRow,samplingPhase=p.Row.Shift=="MIDDLE"?"MIDDLE":"OPEN",samplingStage=p.Row.Stage,timeBasis="report shift test"}),"Initial");
static DateTimeOffset MeasuredAt(ChemicalRow r)=>new(DateTime.ParseExact(r.Day+(r.Shift=="MIDDLE"?" 12:00:00":" 00:00:00"),"yyyy-MM-dd HH:mm:ss",CultureInfo.InvariantCulture),TimeSpan.FromHours(8));
static void Guard(string? env,SqlConnectionStringBuilder b,string db){if(env!="test"||b.DataSource.Split(',')[0].Replace("tcp:","")!="172.16.110.16"||b.InitialCatalog!=db)throw new Exception("Environment guard failed");}
static async Task ActualGuard(AppDbContext db,string expected){await using var c=db.Database.GetDbConnection().CreateCommand();c.CommandText="SELECT DB_NAME()";if((string?)await c.ExecuteScalarAsync()!=expected)throw new Exception("Actual DB guard failed");}
static async Task ActualGuardSql(SqlConnection db,string expected){using var c=db.CreateCommand();c.CommandText="SELECT DB_NAME()";if((string?)await c.ExecuteScalarAsync()!=expected)throw new Exception("Actual DB guard failed");}
static async Task<object> Backup(SqlConnectionStringBuilder b,string db){await using var c=new SqlConnection(b.ConnectionString);await c.OpenAsync();using var cmd=c.CreateCommand();cmd.CommandText="SELECT CONVERT(nvarchar(4000),SERVERPROPERTY('InstanceDefaultBackupPath'))";var dir=(string)(await cmd.ExecuteScalarAsync())!;var path=Path.Combine(dir,$"{db}_TRANSFILES_NOV_1110_{DateTime.Now:yyyyMMdd_HHmmss}.bak");cmd.CommandTimeout=300;cmd.CommandText=$"BACKUP DATABASE [{db}] TO DISK=@p WITH COPY_ONLY,CHECKSUM,INIT";cmd.Parameters.AddWithValue("@p",path);await cmd.ExecuteNonQueryAsync();cmd.CommandText="RESTORE VERIFYONLY FROM DISK=@p WITH CHECKSUM";await cmd.ExecuteNonQueryAsync();return new{database=db,path,copyOnly=true,checksum=true,verifyOnly=true};}
static async Task<int> EnsureCoverage(AppDbContext db,IReadOnlyList<ChemicalPlan> rows,string actor){var count=0;var zone=TimeZoneInfo.FindSystemTimeZoneById("Taipei Standard Time");foreach(var group in rows.GroupBy(x=>x.Ppc.Id)){var policy=await db.ChemicalFormulaPolicies.SingleAsync(x=>x.PartProcessCharacteristicId==group.Key);var effects=await db.ChemicalFormulaEffectivities.AsNoTracking().Where(x=>x.PartProcessCharacteristicId==group.Key&&x.ScheduleRevisionId==policy.ActiveScheduleRevisionId).OrderBy(x=>x.EffectiveFromUtc).ToListAsync();var additions=new List<ChemicalFormulaEffectivity>();foreach(var day in group.Select(x=>DateTime.ParseExact(x.Row.Day,"yyyy-MM-dd",CultureInfo.InvariantCulture)).Distinct().OrderBy(x=>x)){var at=TimeZoneInfo.ConvertTimeToUtc(DateTime.SpecifyKind(day,DateTimeKind.Unspecified),zone);if(effects.Any(x=>x.EffectiveFromUtc<=at&&(x.EffectiveUntilUtcExclusive==null||at<x.EffectiveUntilUtcExclusive)))continue;var prior=effects.Where(x=>x.EffectiveUntilUtcExclusive<=at).OrderByDescending(x=>x.EffectiveUntilUtcExclusive).FirstOrDefault()??throw new Exception($"No prior formula schedule for {group.Key}/{day:yyyy-MM-dd}");additions.Add(new(){PartProcessCharacteristicId=group.Key,FormulaVersionId=prior.FormulaVersionId,FTableHistoryId=prior.FTableHistoryId,EffectiveFromUtc=at,EffectiveUntilUtcExclusive=at.AddDays(1)});}if(additions.Count==0)continue;var all=effects.Concat(additions).OrderBy(x=>x.EffectiveFromUtc).ToList();for(var i=1;i<all.Count;i++)if(all[i-1].EffectiveUntilUtcExclusive is null||all[i-1].EffectiveUntilUtcExclusive>all[i].EffectiveFromUtc)throw new Exception("Schedule overlap");var revision=new ChemicalFormulaScheduleRevision{PartProcessCharacteristicId=group.Key,RevisionNo=(await db.ChemicalFormulaScheduleRevisions.Where(x=>x.PartProcessCharacteristicId==group.Key).MaxAsync(x=>(int?)x.RevisionNo)??0)+1,Actor=actor,Reason="2026-11-10 十一月測試匯入補齊來源日期排程",CreatedAtUtc=DateTime.UtcNow};db.Add(revision);await db.SaveChangesAsync();foreach(var item in all)db.Add(new ChemicalFormulaEffectivity{PartProcessCharacteristicId=group.Key,ScheduleRevisionId=revision.Id,FormulaVersionId=item.FormulaVersionId,FTableHistoryId=item.FTableHistoryId,EffectiveFromUtc=item.EffectiveFromUtc,EffectiveUntilUtcExclusive=item.EffectiveUntilUtcExclusive});await db.SaveChangesAsync();revision.PublishedAtUtc=DateTime.UtcNow;policy.ActiveScheduleRevisionId=revision.Id;await db.SaveChangesAsync();count+=additions.Count;}return count;}
static Guid StableGuid(string v)=>new(SHA256.HashData(Encoding.UTF8.GetBytes(v))[..16]);
static async Task<int> PortalId(EtchReportRequest r,SqlConnection c){using var cmd=new SqlCommand("SELECT Id FROM etch_amount_reports WHERE ReportDate=@d AND LineCode=@l",c);cmd.Parameters.AddWithValue("@d",r.ReportDate);cmd.Parameters.AddWithValue("@l",r.LineCode);var x=await cmd.ExecuteScalarAsync();return x is null?0:Convert.ToInt32(x);}
static async Task<int> EnsurePortal(EtchReportRequest r,SqlConnection c,string actor){await using var tx=(SqlTransaction)await c.BeginTransactionAsync(IsolationLevel.Serializable);using var find=new SqlCommand("SELECT Id FROM etch_amount_reports WITH(UPDLOCK,HOLDLOCK) WHERE ReportDate=@d AND LineCode=@l",c,tx);find.Parameters.AddWithValue("@d",r.ReportDate);find.Parameters.AddWithValue("@l",r.LineCode);var old=await find.ExecuteScalarAsync();if(old is not null){await tx.CommitAsync();return Convert.ToInt32(old);}var a=r.Points.Where(p=>p.Side=="A").Select(p=>p.BeforeValue-p.AfterValue).ToList();var b=r.Points.Where(p=>p.Side=="B").Select(p=>p.BeforeValue-p.AfterValue).ToList();var all=a.Concat(b).ToList();decimal Range(List<decimal> v)=>v.Max()-v.Min();decimal Uniform(List<decimal> v)=>v.Average()==0?0:1-Range(v)/(2*v.Average());var length=EtchReportSyncService.Rule(r.LineCode).Length;var rate=all.Average()*r.LineSpeed/length;var speedRef=r.LineCode switch{"PT1" or "PT2"=>.3m,"QE1"=>1.8m,_=>1.5m};using var insert=new SqlCommand("INSERT INTO etch_amount_reports (ReportDate,LineCode,LineSpeed,OperatorName,FormulaVersion,AverageEtch,EtchRate,RecommendedSpeed,ASideAverage,BSideAverage,ASideRange,BSideRange,TotalRange,AUniformity,BUniformity,TotalUniformity,CreatedAt,UpdatedAt,UpdatedBy,SpcSyncStatus) OUTPUT INSERTED.Id VALUES (@date,@line,@speed,@operator,'PD-3-581-06B-2026',@avg,@rate,@recommended,@a,@b,@ar,@br,@tr,@au,@bu,@tu,GETDATE(),GETDATE(),@actor,'Pending')",c,tx);var pars=new Dictionary<string,object>{{"date",r.ReportDate},{"line",r.LineCode},{"speed",r.LineSpeed},{"operator",r.OperatorName},{"avg",all.Average()},{"rate",rate},{"recommended",length*rate/speedRef},{"a",a.Average()},{"b",b.Average()},{"ar",Range(a)},{"br",Range(b)},{"tr",Range(all)},{"au",Uniform(a)},{"bu",Uniform(b)},{"tu",Uniform(all)},{"actor",actor}};foreach(var p in pars)insert.Parameters.AddWithValue("@"+p.Key,p.Value);var id=Convert.ToInt32(await insert.ExecuteScalarAsync());foreach(var p in r.Points){using var point=new SqlCommand("INSERT INTO etch_amount_points (ReportId,Side,RepeatNo,OpNo,BeforeValue,AfterValue,EtchAmount) VALUES (@id,@side,@r,@op,@before,@after,@amount)",c,tx);point.Parameters.AddWithValue("@id",id);point.Parameters.AddWithValue("@side",p.Side);point.Parameters.AddWithValue("@r",p.RepeatNo);point.Parameters.AddWithValue("@op",p.OpNo);point.Parameters.AddWithValue("@before",p.BeforeValue);point.Parameters.AddWithValue("@after",p.AfterValue);point.Parameters.AddWithValue("@amount",p.BeforeValue-p.AfterValue);await point.ExecuteNonQueryAsync();}await tx.CommitAsync();return id;}

record ChemicalRow(string Key,string Day,string Shift,string Stage,string Line,string Slot,string Item,decimal Primary,decimal Concentration,string File,string Sheet,int SourceRow,string Hash);
record ChemicalPlan(ChemicalRow Row,PartProcessCharacteristic Ppc);
